static int pl011_fifo_to_tty ( struct uart_amba_port * uap ) { u16 status ; unsigned int ch , flag , max_count = 256 ; int fifotaken = 0 ; while ( max_count -- ) { status = pl011_read ( uap , REG_FR ) ; if ( status & UART01x_FR_RXFE ) { break ; } ch = pl011_read ( uap , REG_DR ) | UART_DUMMY_DR_RX ; flag = TTY_NORMAL ; uap -> port . icount . rx ++ ; fifotaken ++ ; if ( unlikely ( ch & UART_DR_ERROR ) ) { if ( ch & UART011_DR_BE ) { ch &= ~ ( UART011_DR_FE | UART011_DR_PE ) ; uap -> port . icount . brk ++ ; } if ( ch & UART011_DR_PE ) { uap -> port . icount . parity ++ ; } if ( ch & UART011_DR_FE ) { uap -> port . icount . frame ++ ; } if ( ch & UART011_DR_OE ) { uap -> port . icount . overrun ++ ; } ch &= uap -> port . read_status_mask ; if ( ch & UART011_DR_BE ) { flag = TTY_BREAK ; } if ( ch & UART011_DR_PE ) { flag = TTY_PARITY ; } if ( ch & UART011_DR_FE ) { flag = TTY_FRAME ; } } if ( uart_handle_sysrq_char ( & uap -> port , ch & 255 ) ) { continue ; } uart_insert_char ( & uap -> port , ch , UART011_DR_OE , ch , flag ) ; } return fifotaken ; } 